19	package org.apache.hadoop.fs.s3a;
20	
21	import javax.annotation.Nonnull;
22	
23	import com.amazonaws.arn.Arn;
24	import com.amazonaws.regions.RegionUtils;
25	
26	/**
27	 * Represents an Arn Resource, this can be an accesspoint or bucket.
28	 */
29	public final class ArnResource {
30	
31	  /**
32	   * Resource name.
33	   */
34	  private final String name;
35	
36	  /**
37	   * Resource owner account id.
38	   */
39	  private final String ownerAccountId;
40	
41	  /**
42	   * Resource region.
43	   */
44	  private final String region;
45	
46	  /**
47	   * Full Arn for the resource.
48	   */
49	  private final String fullArn;
50	
51	  /**
52	   * Partition for the resource. Allowed partitions: aws, aws-cn, aws-us-gov
53	   */
54	  private final String partition;
55	
56	  /**
57	   * Because of the different ways an endpoint can be constructed depending on partition we're
58	   * relying on the AWS SDK to produce the endpoint. In this case we need a region key of the form
59	   * {@code String.format("accesspoint-%s", awsRegion)}
60	   */
61	  private final String accessPointRegionKey;
62	
63	  private ArnResource(String name, String owner, String region, String partition, String fullArn) {
64	    this.name = name;
65	    this.ownerAccountId = owner;
66	    this.region = region;
67	    this.partition = partition;
68	    this.fullArn = fullArn;
69	    this.accessPointRegionKey = String.format("accesspoint-%s", region);
70	  }
71	
72	  /**
73	   * Resource name.
74	   * @return resource name.
75	   */
76	  public String getName() {
77	    return name;
78	  }
79	
80	  /**
81	   * Return owner's account id.
82	   * @return owner account id
83	   */
84	  public String getOwnerAccountId() {
85	    return ownerAccountId;
86	  }
87	
88	  /**
89	   * Resource region.
90	   * @return resource region.
91	   */
92	  public String getRegion() {
93	    return region;
94	  }
95	
96	  /**
97	   * Full arn for resource.
98	   * @return arn for resource.
99	   */
100	  public String getFullArn() {
101	    return fullArn;
102	  }
103	
104	  /**
105	   * Formatted endpoint for the resource.
106	   * @return resource endpoint.
107	   */
108	  public String getEndpoint() {
109	    return RegionUtils.getRegion(accessPointRegionKey)
110	        .getServiceEndpoint("s3");
111	  }
112	
113	  /**
114	   * Parses the passed `arn` string into a full ArnResource.
115	   * @param arn - string representing an Arn resource.
116	   * @return new ArnResource instance.
117	   * @throws IllegalArgumentException - if the Arn is malformed or any of the region, accountId and
118	   * resource name properties are empty.
119	   */
120	  @Nonnull
121	  public static ArnResource accessPointFromArn(String arn) throws IllegalArgumentException {
122	    Arn parsed = Arn.fromString(arn);
123	
124	    if (parsed.getRegion().isEmpty() || parsed.getAccountId().isEmpty() ||
125	        parsed.getResourceAsString().isEmpty()) {
126	      throw new IllegalArgumentException(
127	          String.format("Access Point Arn %s has an invalid format or missing properties", arn));
128	    }
129	
130	    String resourceName = parsed.getResource().getResource();
131	    return new ArnResource(resourceName, parsed.getAccountId(), parsed.getRegion(),
132	        parsed.getPartition(), arn);
133	  }
134	}
