19	package org.apache.hadoop.fs.s3a;
20	
21	import com.amazonaws.regions.Regions;
22	import org.junit.Test;
23	import org.slf4j.Logger;
24	import org.slf4j.LoggerFactory;
25	
26	import org.apache.hadoop.test.HadoopTestBase;
27	
28	import static org.apache.hadoop.test.LambdaTestUtils.intercept;
29	
30	public class TestArnResource extends HadoopTestBase {
31	  private final static Logger LOG = LoggerFactory.getLogger(TestArnResource.class);
32	
33	  @Test
34	  public void parseAccessPointFromArn() throws IllegalArgumentException {
35	    describe("Parse AccessPoint ArnResource from arn string");
36	
37	    String accessPoint = "testAp";
38	    String accountId = "123456789101";
39	    String[][] regionPartitionEndpoints = new String[][] {
40	        {Regions.EU_WEST_1.getName(), "aws", "s3-accesspoint.eu-west-1.amazonaws.com"},
41	        {Regions.US_GOV_EAST_1.getName(), "aws-us-gov",
42	            "s3-accesspoint.us-gov-east-1.amazonaws.com"},
43	        {Regions.CN_NORTH_1.getName(), "aws-cn", "s3-accesspoint.cn-north-1.amazonaws.com.cn"},
44	    };
45	
46	    for (String[] testPair : regionPartitionEndpoints) {
47	      String region = testPair[0];
48	      String partition = testPair[1];
49	      String endpoint = testPair[2];
50	
51	      // arn:partition:service:region:account-id:resource-type/resource-id
52	      String arn = String.format("arn:%s:s3:%s:%s:accesspoint/%s", partition, region, accountId,
53	          accessPoint);
54	
55	      ArnResource resource = ArnResource.accessPointFromArn(arn);
56	      assertEquals("Arn does not match", arn, resource.getFullArn());
57	      assertEquals("Access Point name does not match", accessPoint, resource.getName());
58	      assertEquals("Account Id does not match", accountId, resource.getOwnerAccountId());
59	      assertEquals("Region does not match", region, resource.getRegion());
60	      assertEquals("Endpoint does not match", endpoint, resource.getEndpoint());
61	    }
62	  }
63	
64	  @Test
65	  public void invalidARNsMustThrow() throws Exception {
66	    describe("Using an invalid ARN format must throw when initializing an ArnResource.");
67	
68	    intercept(IllegalArgumentException.class, () ->
69	        ArnResource.accessPointFromArn("invalid:arn:resource"));
70	  }
71	
72	  private void describe(String message) {
73	    LOG.info(message);
74	  }
75	}
